using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

/// <summary>
/// Shared setup for evaluation scenarios: configures telemetry, quality evaluators, and reporting.
/// </summary>
internal static class EvalSetup
{
    private static readonly string ResultsDir =
        Path.Combine(AppContext.BaseDirectory, "eval-results");

    public static ReportingConfiguration CreateReportingConfiguration(
        string scenarioName,
        IChatClient chatClient,
        IEnumerable<IEvaluator>? additionalEvaluators = null)
    {
        var evaluators = new List<IEvaluator>
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        if (additionalEvaluators is not null)
        {
            evaluators.AddRange(additionalEvaluators);
        }

        return new ReportingConfiguration(
            storageForScenarioRunResults:
                new DiskBasedResultStore(ResultsDir),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(chatClient));
    }
}

using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that OpenTelemetry traces are emitted for chat interactions.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static readonly ActivitySource Source = new("MyApp.Evals.Telemetry");

    [TestMethod]
    public async Task ChatCompletion_EmitsTrace()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = src => src.Name == "Microsoft.Extensions.AI"
                                     || src.Name == Source.Name,
            Sample = (ref ActivityCreationOptions<ActivityContext> _) =>
                ActivitySamplingResult.AllDataAndRecorded,
            ActivityStarted = a => activities.Add(a),
        };
        ActivitySource.AddActivityListener(listener);

        var client = new ChatClientBuilder(
                new OllamaChatClient(new Uri("http://localhost:11434"), "llama3"))
            .UseOpenTelemetry(sourceName: "Microsoft.Extensions.AI")
            .Build();

        using var activity = Source.StartActivity("eval-telemetry");

        var response = await client.GetResponseAsync("Say hello in one word.");

        Assert.IsTrue(
            activities.Any(a => a.OperationName.Contains("chat", StringComparison.OrdinalIgnoreCase)),
            "Expected at least one activity for the chat completion call.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates response quality using AI-judge evaluators (relevance, coherence, etc.).
/// </summary>
[TestClass]
public class QualityTests
{
    private static IChatClient JudgeClient => new OllamaChatClient(
        new Uri("http://localhost:11434"), "llama3");

    private static IChatClient TargetClient => new OllamaChatClient(
        new Uri("http://localhost:11434"), "llama3");

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        var reportingConfig = EvalSetup.CreateReportingConfiguration(
            scenarioName: nameof(CoachResponse_MeetsQualityBar),
            chatClient: JudgeClient);

        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_MeetsQualityBar));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "How can I improve my morning routine to be more productive?"),
        };

        var response = await TargetClient.GetResponseAsync(messages);
        messages.AddRange(response.ToChatMessages());

        await scenario.EvaluateAsync(messages, response);

        foreach (var metric in scenario.GetAllMetricResults())
        {
            if (metric is NumericMetricResult numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"Quality metric '{metric.Name}' scored {numeric.Value}/5, below threshold of 3.");
            }
        }
    }

    [TestMethod]
    public async Task CoachResponse_IsGrounded()
    {
        var reportingConfig = EvalSetup.CreateReportingConfiguration(
            scenarioName: nameof(CoachResponse_IsGrounded),
            chatClient: JudgeClient);

        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_IsGrounded));

        var context =
            "Research shows that waking at a consistent time each day improves alertness.";

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "When should I wake up for better energy?"),
        };

        var response = await TargetClient.GetResponseAsync(messages);
        messages.AddRange(response.ToChatMessages());

        await scenario.EvaluateAsync(
            messages,
            response,
            additionalContext:
            [
                new EvaluationContext("grounding", context),
            ]);

        var groundedness = scenario.GetAllMetricResults()
            .OfType<NumericMetricResult>()
            .FirstOrDefault(m => m.Name == GroundednessEvaluator.GroundednessMetricName);

        Assert.IsNotNull(groundedness);
        Assert.IsTrue(
            groundedness.Value >= 3,
            $"Groundedness scored {groundedness.Value}/5, below threshold of 3.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompt against multiple model configurations
/// and produces side-by-side quality metrics for comparison.
/// </summary>
[TestClass]
public class CompareTests
{
    private static IChatClient JudgeClient => new OllamaChatClient(
        new Uri("http://localhost:11434"), "llama3");

    private record ModelVariant(string Name, string ModelId);

    private static readonly ModelVariant[] Variants =
    [
        new("baseline", "llama3"),
        new("candidate", "llama3:instruct"),
    ];

    [TestMethod]
    public async Task CompareVariants_QualityMetrics()
    {
        var prompt = "Give me three tips for staying focused while working from home.";
        var results = new Dictionary<string, IReadOnlyList<MetricResult>>();

        foreach (var variant in Variants)
        {
            var client = new OllamaChatClient(
                new Uri("http://localhost:11434"), variant.ModelId);

            var reportingConfig = EvalSetup.CreateReportingConfiguration(
                scenarioName: $"Compare_{variant.Name}",
                chatClient: JudgeClient);

            await using var scenario = await reportingConfig.CreateScenarioRunAsync(
                scenarioName: $"Compare_{variant.Name}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, prompt),
            };

            var response = await client.GetResponseAsync(messages);
            messages.AddRange(response.ToChatMessages());

            await scenario.EvaluateAsync(messages, response);

            results[variant.Name] = scenario.GetAllMetricResults().ToList();
        }

        // Log comparison summary
        Console.WriteLine("=== Model Comparison Results ===");
        Console.WriteLine($"{"Metric",-20} {"baseline",10} {"candidate",10} {"Delta",10}");
        Console.WriteLine(new string('-', 52));

        var baselineMetrics = results["baseline"].OfType<NumericMetricResult>().ToList();
        var candidateMetrics = results["candidate"].OfType<NumericMetricResult>().ToList();

        foreach (var baseline in baselineMetrics)
        {
            var candidate = candidateMetrics.FirstOrDefault(m => m.Name == baseline.Name);
            if (candidate is not null)
            {
                var delta = candidate.Value - baseline.Value;
                var sign = delta >= 0 ? "+" : "";
                Console.WriteLine(
                    $"{baseline.Name,-20} {baseline.Value,10:F2} {candidate.Value,10:F2} {sign}{delta,9:F2}");
            }
        }

        // Ensure at least one variant meets quality bar
        Assert.IsTrue(
            baselineMetrics.Concat(candidateMetrics).Any(m => m.Value >= 3),
            "Neither variant met the minimum quality threshold.");
    }
}

