+using Microsoft.Extensions.AI;
+using Microsoft.Extensions.AI.Evaluation;
+using Microsoft.Extensions.AI.Evaluation.Quality;
+using Microsoft.Extensions.AI.Evaluation.Reporting;
+using Microsoft.VisualStudio.TestTools.UnitTesting;
+
+namespace MyApp.Evals;
+
+/// <summary>
+/// Compare mode: runs the same prompt against multiple model configurations
+/// and produces side-by-side quality metrics for comparison.
+/// </summary>
+[TestClass]
+public class CompareTests
+{
+    private static IChatClient JudgeClient => new OllamaChatClient(
+        new Uri("http://localhost:11434"), "llama3");
+
+    private record ModelVariant(string Name, string ModelId);
+
+    private static readonly ModelVariant[] Variants =
+    [
+        new("baseline", "llama3"),
+        new("candidate", "llama3:instruct"),
+    ];
+
+    [TestMethod]
+    public async Task CompareVariants_QualityMetrics()
+    {
+        var prompt = "Give me three tips for staying focused while working from home.";
+        var results = new Dictionary<string, IReadOnlyList<MetricResult>>();
+
+        foreach (var variant in Variants)
+        {
+            var client = new OllamaChatClient(
+                new Uri("http://localhost:11434"), variant.ModelId);
+
+            var reportingConfig = EvalSetup.CreateReportingConfiguration(
+                scenarioName: $"Compare_{variant.Name}",
+                chatClient: JudgeClient);
+
+            await using var scenario = await reportingConfig.CreateScenarioRunAsync(
+                scenarioName: $"Compare_{variant.Name}");
+
+            var messages = new List<ChatMessage>
+            {
+                new(ChatRole.User, prompt),
+            };
+
+            var response = await client.GetResponseAsync(messages);
+            messages.AddRange(response.ToChatMessages());
+
+            await scenario.EvaluateAsync(messages, response);
+
+            results[variant.Name] = scenario.GetAllMetricResults().ToList();
+        }
+
+        // Log comparison summary
+        Console.WriteLine("=== Model Comparison Results ===");
+        Console.WriteLine($"{"Metric",-20} {"baseline",10} {"candidate",10} {"Delta",10}");
+        Console.WriteLine(new string('-', 52));
+
+        var baselineMetrics = results["baseline"].OfType<NumericMetricResult>().ToList();
+        var candidateMetrics = results["candidate"].OfType<NumericMetricResult>().ToList();
+
+        foreach (var baseline in baselineMetrics)
+        {
+            var candidate = candidateMetrics.FirstOrDefault(m => m.Name == baseline.Name);
+            if (candidate is not null)
+            {
+                var delta = candidate.Value - baseline.Value;
+                var sign = delta >= 0 ? "+" : "";
+                Console.WriteLine(
+                    $"{baseline.Name,-20} {baseline.Value,10:F2} {candidate.Value,10:F2} {sign}{delta,9:F2}");
+            }
+        }
+
+        // Ensure at least one variant meets quality bar
+        Assert.IsTrue(
+            baselineMetrics.Concat(candidateMetrics).Any(m => m.Value >= 3),
+            "Neither variant met the minimum quality threshold.");
+    }
+}
